            'liq.ui.injplate_not_analyzed': 'Injector plate ({material}): structural check not run - {reason}',
            'liq.ui.injplate_na_pintle': 'pintle face: a single central annulus bore instead of a drilled hole field; the drilled-plate model does not apply and an annular-plate case is not implemented in this version.',
            'liq.ui.injplate_na_coax_swirl': 'coaxial swirl elements: the face penetration of each element is not published by the injector circuit model.',
            'liq.ui.injplate_na_swirl': 'pressure-swirl elements: the swirl chamber penetrating the face is an assumption, not a solved hole plan.',
