            'liq.ui.gimbal_range': 'Gimbal Açı Aralığı',
            'liq.ui.gimbal_actuator_arm': 'Gimbal Aktüatör Kolu',
            'liq.ui.perpendicular_distance_from_the_gimbal_pivot': 'Gimbal pivot ekseninden aktüatörün etki doğrusuna dik uzaklık (moment kolu). Aktüatör strokunu ve verilen momenti karşılamak için gereken kuvveti belirler. Bilinmiyorsa boş bırakın - varsayılan kabul edilmez ve yük zinciri hesaplanmaz.',
            'liq.ui.mount_ring_offset': 'Montaj Halkası Mesafesi',
